# Run from the repository root: Rscript tests/reference/copula_probe.R
# Writes data/copula3.csv (once; it is committed and never regenerated by the tests) and prints, for every
# Copula-DCC case of plan 4b, rmgarch's numbers next to an independent evaluation of the formulas in
# docs/superpowers/plans/2026-11-13-volengine-04b-rmgarch-copula-notes.md.
suppressPackageStartupMessages({
    library(rmgarch)
})
options(digits = 15)

reference <- file.path("tests", "reference")
data_file <- file.path(reference, "data", "copula3.csv")

# Three sGARCH(1,1) series with standardized-t(7) margins joined by a Student-t(6) DCC(0.04, 0.93) copula.
simulate_panel <- function() {
    set.seed(20261113)
    n <- 2000
    m <- 3
    nu <- 6
    qbar <- matrix(c(1, 0.5, 0.3, 0.5, 1, 0.4, 0.3, 0.4, 1), 3)
    q <- qbar
    eps_prev <- rep(0, m)
    garch <- list(omega = c(0.02, 0.05, 0.03), alpha = c(0.07, 0.09, 0.05), beta = c(0.91, 0.87, 0.93))
    h <- garch$omega / (1 - garch$alpha - garch$beta)
    x <- matrix(0, n, m)
    for (t in 1:n) {
        q <- (1 - 0.04 - 0.93) * qbar + 0.04 * tcrossprod(eps_prev) + 0.93 * q
        d <- 1 / sqrt(diag(q))
        r <- q * outer(d, d)
        w <- rchisq(1, nu)
        y <- as.numeric(t(chol(r)) %*% rnorm(m)) * sqrt((nu - 2) / w)
        u <- pdist("std", y, shape = nu)
        eps_prev <- y
        z <- qdist("std", u, shape = 7)
        x[t, ] <- sqrt(h) * z
        h <- garch$omega + garch$alpha * x[t, ]^2 + garch$beta * h
    }
    colnames(x) <- c("A", "B", "C")
    write.csv(x, data_file, row.names = FALSE)
}

if (!file.exists(data_file)) simulate_panel()
data <- as.matrix(read.csv(data_file))
m <- ncol(data)
n <- nrow(data)

uspec <- ugarchspec(variance.model = list(model = "sGARCH", garchOrder = c(1, 1)),
                    mean.model = list(armaOrder = c(0, 0)), distribution.model = "std")
mspec <- multispec(replicate(m, uspec))
mfit <- multifit(mspec, data, solver = "solnp", solver.control = list(tol = 1e-10))
stopifnot(all(vapply(mfit@fit, function(x) x@fit$convergence == 0, TRUE)))
cat("univariate coefficients\n")
print(sapply(mfit@fit, coef))
z <- sapply(mfit@fit, function(f) residuals(f) / sigma(f))
univariate_llh <- sum(sapply(mfit@fit, function(f) f@fit$LLH))
shapes <- sapply(mfit@fit, function(f) coef(f)["shape"])
cat("sum univariate llh", univariate_llh, "\n")

# --- independent evaluation (formulas of the notes) ---
clamp <- function(u) {
    u[u > 0.99999] <- 0.99999
    u[u < 1.5 * .Machine$double.eps] <- .Machine$double.eps
    u
}
uniforms <- function(how) {
    if (how == "parametric") return(clamp(sapply(1:m, function(i) pdist("std", z[, i], shape = shapes[i]))))
    clamp(apply(z, 2, function(x) rank(x) / length(x)))
}
log_mvnorm <- function(e, r) {
    l <- chol(r)
    q <- colSums(backsolve(l, t(e), transpose = TRUE)^2)
    -0.5 * (m * log(2 * pi) + 2 * sum(log(diag(l))) + q)
}
log_mvt <- function(e, r, nu) {
    l <- chol(r)
    q <- colSums(backsolve(l, t(e), transpose = TRUE)^2)
    lgamma((nu + m) / 2) - lgamma(nu / 2) - m / 2 * log(pi * (nu - 2)) - sum(log(diag(l))) -
        (nu + m) / 2 * log1p(q / (nu - 2))
}
scores <- function(u, nu) if (is.null(nu)) qnorm(u) else matrix(qdist("std", u, shape = nu), ncol = m)
marginal <- function(e, nu) if (is.null(nu)) sum(dnorm(e, log = TRUE)) else sum(log(ddist("std", e, shape = nu)))
# rmgarch's dynamic recursion: Qbar = cov(e), Nbar = cov(n) (centred), presample e_s = n_s = 0.
dynamic_path <- function(e, a, b, g) {
    qbar <- cov(e)
    nn <- e * (e < 0)
    nbar <- cov(nn)
    q <- qbar
    out <- vector("list", n)
    ep <- np <- rep(0, m)
    for (t in 1:n) {
        q <- (1 - a - b) * qbar - g * nbar + a * tcrossprod(ep) + g * tcrossprod(np) + b * q
        d <- 1 / sqrt(diag(q))
        out[[t]] <- q * outer(d, d)
        ep <- e[t, ]
        np <- nn[t, ]
    }
    out
}
from_free <- function(x) {
    a <- diag(m)
    a[lower.tri(a)] <- x
    cov2cor(a %*% t(a))
}

joint <- function(cf, name, default = 0) if (name %in% names(cf)) cf[[name]] else default

evaluate <- function(case, fit) {
    cf <- coef(fit)
    names(cf) <- sub("^\\[Joint\\]", "", names(cf))
    u <- uniforms(case$transformation)
    nu <- NULL
    if (case$copula == "mvt") nu <- joint(cf, "mshape", case$fixed$mshape)
    e <- scores(u, nu)
    if (case$time_varying) {
        path <- dynamic_path(e, cf[["dcca1"]], cf[["dccb1"]], joint(cf, "dccg1"))
        dens <- sapply(1:n, function(t) {
            if (is.null(nu)) return(log_mvnorm(e[t, , drop = FALSE], path[[t]]))
            log_mvt(e[t, , drop = FALSE], path[[t]], nu)
        })
        return(univariate_llh + sum(dens) - marginal(e, nu))
    }
    r <- NULL
    if ("C1" %in% names(cf)) r <- from_free(cf[grep("^C[0-9]", names(cf))])
    if (is.null(r) && is.null(nu)) r <- cor(e)
    if (is.null(r)) r <- sin(pi * cor(e, method = "kendall") / 2)
    dens <- if (is.null(nu)) log_mvnorm(e, r) else log_mvt(e, r, nu)
    univariate_llh + sum(dens) - marginal(e, nu)
}

cases <- list(
    list(id = "static_mvnorm_kendall_param", copula = "mvnorm", method = "Kendall", time_varying = FALSE, transformation = "parametric"),
    list(id = "static_mvnorm_ml_param", copula = "mvnorm", method = "ML", time_varying = FALSE, transformation = "parametric"),
    list(id = "static_mvnorm_ml_emp", copula = "mvnorm", method = "ML", time_varying = FALSE, transformation = "empirical"),
    list(id = "static_mvt_kendall_param", copula = "mvt", method = "Kendall", time_varying = FALSE, transformation = "parametric"),
    list(id = "static_mvt_kendall_emp", copula = "mvt", method = "Kendall", time_varying = FALSE, transformation = "empirical"),
    list(id = "static_mvt_ml_param", copula = "mvt", method = "ML", time_varying = FALSE, transformation = "parametric"),
    list(id = "dcc_mvnorm_param", copula = "mvnorm", time_varying = TRUE, transformation = "parametric"),
    list(id = "dcc_mvnorm_emp", copula = "mvnorm", time_varying = TRUE, transformation = "empirical"),
    list(id = "dcc_mvt_param", copula = "mvt", time_varying = TRUE, transformation = "parametric"),
    list(id = "dcc_mvt_emp", copula = "mvt", time_varying = TRUE, transformation = "empirical"),
    list(id = "adcc_mvnorm_param", copula = "mvnorm", time_varying = TRUE, asymmetric = TRUE, transformation = "parametric"),
    list(id = "adcc_mvt_param", copula = "mvt", time_varying = TRUE, asymmetric = TRUE, transformation = "parametric"),
    list(id = "dcc_mvt_param_shape8", copula = "mvt", time_varying = TRUE, transformation = "parametric", fixed = list(mshape = 8))
)

fit_case <- function(case) {
    method <- if (is.null(case$method)) "ML" else case$method
    asymmetric <- isTRUE(case$asymmetric)
    fixed <- if (is.null(case$fixed)) list() else case$fixed
    spec <- cgarchspec(mspec, dccOrder = c(1, 1), asymmetric = asymmetric, fixed.pars = fixed,
                       distribution.model = list(copula = case$copula, method = method,
                                                 time.varying = case$time_varying,
                                                 transformation = case$transformation))
    cgarchfit(spec, data, fit = mfit, fit.control = list(eval.se = TRUE))
}

for (case in cases) {
    fit <- fit_case(case)
    mine <- evaluate(case, fit)
    cat(sprintf("\n== %s  convergence %d\n", case$id, fit@mfit$convergence))
    cat(sprintf("llh rmgarch %.10f  independent %.10f  diff %.3e\n", likelihood(fit), mine, likelihood(fit) - mine))
    joint_rows <- grep("Joint", rownames(fit@mfit$matcoef))
    if (length(joint_rows)) print(fit@mfit$matcoef[joint_rows, 1:2, drop = FALSE])
    rt <- fit@mfit$Rt
    if (is.list(rt)) {
        for (t in c(1, n / 2, n)) cat("R_", t, ":", rt[[t]][lower.tri(rt[[t]])], "\n")
    } else {
        cat("R:", rt[lower.tri(rt)], "\n")
    }
}
